def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def clean_env(toolchain=None):
    return {'PATH': (str(toolchain)+os.pathsep if toolchain else '')+os.defpath,
            'LC_ALL':'C','PYTHONDONTWRITEBYTECODE':'1','GIT_CONFIG_NOSYSTEM':'1',
            'GIT_CONFIG_GLOBAL':'/dev/null','GIT_TERMINAL_PROMPT':'0','GIT_OPTIONAL_LOCKS':'0',
            'GIT_ALLOW_PROTOCOL':'file','PGPASSFILE':'/dev/null','PGSERVICEFILE':'/dev/null'}


def load_payload():
    raw=zlib.decompress(base64.b85decode(PAYLOAD_B85))
    require(sha(raw)==PAYLOAD_SHA,'PAYLOAD_HASH_MISMATCH')
    data=json.loads(raw)
    require(data['base']==BASE and data['branch']=='meta-ads-api','PAYLOAD_BASE_MISMATCH')
    require(set(data['files'])==set(ALLOWLIST),'PAYLOAD_FILE_SCOPE')
    for name,entry in data['files'].items():
        p=PurePosixPath(name)
        require(not p.is_absolute() and '..' not in p.parts and p.parts[0] in ('scripts','src')
                and str(p)==name,'UNSAFE_PAYLOAD_PATH')
        require(sha(base64.b64decode(entry['data'],validate=True))==entry['sha256'],'PAYLOAD_FILE_HASH:'+name)
    return data


def resolve_directory(path):
    path=path.expanduser().absolute()
    require(not path.is_relative_to(PROTECTED) and not path.is_symlink(),'PROTECTED_OR_SYMLINK_DIRECTORY')
    resolved=path.resolve(strict=True)
    require(not resolved.is_relative_to(PROTECTED) and resolved.is_dir(),'PROTECTED_OR_INVALID_DIRECTORY')
    return resolved


def child_file(root, name):
    p=PurePosixPath(name)
    require(not p.is_absolute() and '..' not in p.parts and str(p)==name,'UNSAFE_CHILD_PATH')
    target=root
    for part in p.parts:
        target=target/part
        require(not target.is_symlink(),'SYMLINK_SOURCE_PATH:'+name)
    require(target.resolve().is_relative_to(root.resolve()),'CHILD_PATH_ESCAPE')
    return target


def output(argv, cwd, env):
    result=subprocess.run([str(a) for a in argv],cwd=cwd,env=env,text=True,capture_output=True,timeout=60)
    require(result.returncode==0,'PREFLIGHT_COMMAND_FAILED:'+Path(str(argv[0])).name)
    return result.stdout.strip()


def git_output(repo, *args):
    return output([GIT,'-c','core.hooksPath=/dev/null','-c','core.fsmonitor=false',*args],repo,clean_env())


def verify_source(repo,data):
    metadata=repo/'.git'
    require(not metadata.is_symlink() and metadata.is_dir(),'SOURCE_GIT_DIR_SCOPE')
    # Reject indirection before asking Git to open repository metadata.
    for parent,dirs,files in os.walk(metadata,followlinks=False):
        for name in dirs+files:
            require(not (Path(parent)/name).is_symlink(),'SOURCE_GIT_SYMLINK_FORBIDDEN')
    require(not (metadata/'objects/info/alternates').exists(),'SOURCE_GIT_ALTERNATES_FORBIDDEN')
    config=(metadata/'config').read_text()
    require(not re.search(r'(?im)^\s*\[\s*include|^\s*worktree\s*=',config),'SOURCE_GIT_INDIRECTION_FORBIDDEN')
    require(git_output(repo,'branch','--show-current')=='meta-ads-api' and git_output(repo,'rev-parse','HEAD')==BASE,
            'SOURCE_BRANCH_OR_HEAD_DRIFT')
    common=Path(git_output(repo,'rev-parse','--git-common-dir'))
    common=(repo/common).resolve() if not common.is_absolute() else common.resolve()
    require(common==repo/'.git' and common.is_dir() and not (repo/'.git').is_symlink(),'SOURCE_GIT_DIR_SCOPE')
    require(not (common/'objects/info/alternates').exists(),'SOURCE_GIT_ALTERNATES_FORBIDDEN')
    dirty=set(filter(None,git_output(repo,'diff','HEAD','--name-only','--no-ext-diff','--no-textconv').splitlines()))
    expected={name for name,entry in data['transfer_files'].items() if entry['base_sha256'] is not None}
    require(dirty==expected,'SOURCE_TRACKED_CHANGE_SCOPE_DRIFT')
    for name,hashes in data['source_files'].items():
        target=child_file(repo,name)
        require(target.is_file() and sha(target.read_bytes()) in hashes,'SOURCE_FILE_DRIFT:'+name)
    for name in set(data['files'])-set(data['source_files']):
        target=child_file(repo,name)
        require(not target.exists() or target.is_file() and sha(target.read_bytes())==data['files'][name]['sha256'],
                'OPTIONAL_PRIOR_FILE_DRIFT:'+name)


def preflight(args,data):
    require(sys.platform=='darwin' and sys.version_info>=(3,9) and os.geteuid()!=0,'MAC_NON_ROOT_PYTHON_3_9_REQUIRED')
    downloads=resolve_directory(Path.home()/'Downloads')
    work=resolve_directory(args.workspace)
    require(work.parent==downloads and work.name.startswith('etrylue-meta-validation-')
            and work.stat().st_uid==os.geteuid(),'SOURCE_WORKSPACE_SCOPE')
    repo=resolve_directory(work/'dashboard-meta-ads-api')
    require(repo.parent==work,'SOURCE_REPOSITORY_SCOPE')
    manifest=json.loads(child_file(work,'transfer-manifest.json').read_text())
    require(manifest['base']==BASE and manifest['branch']=='meta-ads-api'
            and manifest['files']==data['transfer_files'],'TRANSFER_MANIFEST_DRIFT')
    verify_source(repo,data)
    runtime=resolve_directory(args.runtime_root)
    require(runtime.parent==downloads and runtime.name=='etrylue-meta-pg17-6'
            and runtime.stat().st_uid==os.geteuid(),'RUNTIME_SCOPE')
    readiness=json.loads(child_file(runtime,'runtime-readiness.json').read_text())
    pg_bin=resolve_directory(runtime/'install/bin')
    require(readiness['status']=='PASS_BINARY_PREPARATION_ONLY' and readiness['uid']==os.geteuid()
            and readiness['pg_bin']==str(pg_bin) and readiness['pgcrypto_control_version']=='1.3','RUNTIME_READINESS_DRIFT')
    for name in ('postgres','initdb','pg_ctl','psql'):
        exe=child_file(pg_bin,name)
        require(exe.is_file() and os.access(exe,os.X_OK)
                and sha(exe.read_bytes())==readiness['versions'][name]['sha256'],'PG_BINARY_DRIFT:'+name)
        require(output([exe,'--version'],work,clean_env()).endswith('17.6'),'PG_VERSION_DRIFT:'+name)
    tool_root=resolve_directory(work/'toolchain')
    toolchain=resolve_directory(tool_root/'bin')
    for name in ('python3','node'):
        exe=(toolchain/name).resolve(strict=True)
        require(exe.is_relative_to(tool_root) and exe.is_file() and os.access(exe,os.X_OK),'TOOLCHAIN_SCOPE:'+name)
    require(output([toolchain/'python3','-c','import sys; print(sys.version_info >= (3,12))'],work,clean_env(toolchain))=='True',
            'HARNESS_PYTHON_3_12_REQUIRED')
    deps=resolve_directory(work/'fixture-tools/node_modules')
    require((repo/'node_modules').resolve(strict=True)==deps,'SOURCE_DEPENDENCIES_SCOPE')
    tsx=json.loads(child_file(deps,'tsx/package.json').read_text())
    require(tsx['version']=='4.22.3','TSX_VERSION_DRIFT')
    gate=child_file(repo,'src/lib/media-sync/media-provider-sync-capabilities.ts')
    require(sha(gate.read_bytes())==data['runtime_gate_sha256'],'RUNTIME_GATE_DRIFT')
    return downloads,work,repo,pg_bin,toolchain,deps


def apply_payload(repo,data):
    # Fresh baseline checkout only. Validate every target before writing any file.
    for name,entry in data['files'].items():
        target=child_file(repo,name)
        if entry['base_sha256'] is None:
            require(not target.exists(),'FRESH_TARGET_ALREADY_EXISTS:'+name)
        else:
            require(target.is_file() and sha(target.read_bytes())==entry['base_sha256'],'FRESH_BASE_DRIFT:'+name)
    for name,entry in data['files'].items():
        target=child_file(repo,name)
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(base64.b64decode(entry['data'],validate=True))
        require(sha(target.read_bytes())==entry['sha256'],'FRESH_WRITE_FAILED:'+name)


def execute(args,data,paths):
    downloads,source_work,source,pg_bin,toolchain,deps=paths
    os.umask(0o077)
    work=Path(tempfile.mkdtemp(prefix='etrylue-meta-page-db-',dir=downloads))
    repo=work/'dashboard-meta-ads-api';log_path=work/'run.log';results=work/'results'
    env=clean_env(toolchain)
    print('WORKSPACE='+str(work),flush=True);print('LOG='+str(log_path),flush=True)
    with log_path.open('x') as log:
        def run(argv,cwd=repo):
            with subprocess.Popen([str(a) for a in argv],cwd=cwd,env=env,stdout=subprocess.PIPE,
                                  stderr=subprocess.STDOUT,text=True,errors='replace') as process:
                for line in process.stdout:
                    print(line,end='',flush=True);log.write(line);log.flush()
                require(process.wait()==0,'LOCAL_CHECK_FAILED; log='+str(log_path))
        try:
            # Local object copy, no network and no shared object alternates/hardlinks.
            run([GIT,'-c','core.hooksPath=/dev/null','clone','--local','--no-hardlinks','--no-checkout',
                 '--single-branch','--branch','meta-ads-api',source,repo],cwd=work)
            require(git_output(repo,'rev-parse','HEAD')==BASE,'FRESH_CLONE_HEAD_DRIFT')
            run([GIT,'-c','core.hooksPath=/dev/null','checkout','meta-ads-api'])
            apply_payload(repo,data)
            (repo/'node_modules').symlink_to(deps,target_is_directory=True)
            (work/'bundle-manifest.json').write_text(json.dumps({'base':BASE,'branch':'meta-ads-api',
                'source_read_only':str(source),'files':{p:e['sha256'] for p,e in data['files'].items()},
                'payload_sha256':PAYLOAD_SHA,'runtime_gate':'DISABLED'},indent=2)+'\n')
            run([toolchain/'node','--import','tsx','scripts/verify-meta-ads-page-checkpoint-sql-contract.ts'])
            run([toolchain/'node','--import','tsx','scripts/verify-meta-ads-page-checkpoint-repository.ts'])
            run([toolchain/'python3','-B','scripts/verify_meta_ads_page_checkpoint_harness.py'])
            argv=[toolchain/'python3','-B','scripts/meta_ads_page_checkpoint_harness.py','--prepare',results]
            if args.run:argv+=['--run-isolated','--pg-bin',pg_bin]
            run(argv)
            verify_source(source,data)
            require(git_output(repo,'rev-parse','HEAD')==BASE and git_output(repo,'branch','--show-current')=='meta-ads-api','FINAL_BRANCH_DRIFT')
            for name,entry in data['files'].items():
                require(sha(child_file(repo,name).read_bytes())==entry['sha256'],'FINAL_FILE_DRIFT:'+name)
            if args.run:
                result_path=results/'runtime-result.json'
                result=json.loads(result_path.read_text())
                require(result['status']=='PASS' and result['same_claim_process_restart'] is True
                        and result['postgres_restart'] is True and result['cas_two_sessions'] is True
                        and result['actual_rollback'] is True and result['claim_transfer']=='REJECTED'
                        and result['canonical_rows']==6 and result['fetched_rows']==7
                        and result['csv_and_common_tables_unchanged'] is True,'PASS_RESULT_INCOMPLETE')
                print('RESULT='+str(result_path),flush=True)
            else:print('PREPARE_ONLY=PASS DB_EXECUTIONS=0',flush=True)
            print('SOURCE_CHECKOUT=UNCHANGED',flush=True);print('LOG='+str(log_path),flush=True)
        except BaseException:
            print('FAILED. Send log: '+str(log_path),file=sys.stderr)
            raise


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    modes=parser.add_mutually_exclusive_group(required=True)
    modes.add_argument('--inspect-payload',action='store_true',help='Read-only embedded file/hash verification, any OS')
    modes.add_argument('--check',action='store_true',help='Read-only Mac workspace/tool preflight; no DB')
    modes.add_argument('--prepare-only',action='store_true',help='Fresh isolated checkout and offline checks; no DB')
    modes.add_argument('--run',action='store_true',help='Fresh isolated checkout and temporary private fixture DB run')
    parser.add_argument('--workspace',type=Path,default=Path.home()/'Downloads/etrylue-meta-validation-yx3bf1m0')
    parser.add_argument('--runtime-root',type=Path,default=Path.home()/'Downloads/etrylue-meta-pg17-6')
    args=parser.parse_args();data=load_payload()
    if args.inspect_payload:
        print(json.dumps({'payload':'PASS','files':len(data['files']),'db_executions':0}));return
    paths=preflight(args,data)
    if args.check:
        print(json.dumps({'preflight':'PASS','files':len(data['files']),'db_executions':0}));return
    execute(args,data,paths)


if __name__=='__main__':
    main()
